"""
Ajoute au warehouse (data/warehouse.seed.json) les jeux de données de la
déclaration désagrégée par projet (Exigence ITIE 4.7 — niveau de
ventilation des paiements et recettes), à partir du fichier fourni par
l'utilisateur « Désagrégation Déclaration par projet.xlsx » (Annexe 60-1 :
illustration de la déclaration des recettes par projet dans le secteur
minier, réparties en 3 catégories de sociétés ; Annexe 60-2 : relevé des
recettes du CAMI de la quotité de droits superficiaires par titre minier,
exercice 2023), et crée un nouveau thème ITIE dédié « Déclaration par
projet (Exigence 4.7) » dans data/warehouse.seed.json (clé theme_info).

Principe (« ne rien cacher, toutes ces données sont publiques ») : les
données de l'Annexe 60-1 et de l'Annexe 60-2 sont reproduites exactement
telles que fournies dans le fichier Excel source, y compris leurs
anomalies et doublons apparents (voir meta.qualite de chaque jeu de
données ci-dessous) — aucune ligne n'est corrigée, fusionnée ou supprimée,
aucun chiffre n'est réestimé.

Le long compte rendu de l'atelier ITIE-RDC / GIZ de mai 2024 sur la
faisabilité de la déclaration par projet (contexte, définitions
retenues, débats, obstacles identifiés) est résumé dans le champ
`desc` (visible uniquement en mode administrateur, conformément à la
convention du site : portail de données d'abord, textes explicatifs
longs réservés au profil administrateur) du jeu de données de synthèse
`dpp_contexte_exigence_4_7`.
"""
from __future__ import annotations

import json
from pathlib import Path

BASE_DIR = Path(__file__).resolve().parent.parent
WAREHOUSE_PATH = BASE_DIR / "data" / "warehouse.seed.json"

SOURCE_XLSX = (
    "« Désagrégation Déclaration par projet.xlsx » (1 feuille), fourni "
    "directement par l'utilisateur (2026-09-24) — reprend l'Annexe 60-1 "
    "(illustration de la déclaration des recettes par projet, secteur "
    "minier, 3 catégories de sociétés) et l'Annexe 60-2 (relevé des "
    "recettes du CAMI de la quotité de droits superficiaires par titre "
    "minier, exercice 2023) au titre de l'Exigence ITIE 4.7 (niveau de "
    "ventilation)."
)

THEME_KEY = "declaration_par_projet"
THEME_LABEL = "Déclaration par projet"

COMMON_META = dict(
    theme=THEME_KEY,
    theme_label=THEME_LABEL,
    source=SOURCE_XLSX,
)

DATASETS: dict = {}


def add(name, label, cat, desc, cols, types, rows, **meta_over):
    meta = dict(COMMON_META)
    meta.update(meta_over)
    DATASETS[name] = dict(label=label, cat=cat, desc=desc, cols=cols, types=types, rows=rows, meta=meta)


